\text{Let } n \in \mathbb{Z}, n > 2, \text{ and let } x_1, x_2, \dots, x_n \in \mathbb{R}^+ \text{ be positive real numbers. Let } r, s, q \in \mathbb{Z}^+ \text{ satisfy } 1 < r < n, \text{ and define } n = r + s. Prove that} 

\begin{align*}
1) \quad &\sum_{i=1}^{n} \frac{x_i^q}{x_{(i+1)}^s + x_{(i+2)}^s + \cdots + x_{(i+r)}^s} \\
&\ge \frac{(x_1^q + x_2^q + \cdots + x_n^q)^2}{(r-1)(x_1^{q+s} + x_2^{q+s} + \cdots + x_n^{q+s})}
\\
2) \quad &\sum_{i=1}^{n} \frac{x_{(i+1)}^s + x_{(i+2)}^s + \cdots + x_{(i+r)}^s}{x_i^q} \\
&\ge \frac{(r-1)(x_1^s + x_2^s + \cdots + x_n^s)^2}{x_1^{q+s} + x_2^{q+s} + \cdots + x_n^{q+s}}
\end{align*}
\text{(Indices are taken modulo } n \text{.)}

